entries[1288912] = { ["name"] = "Unlock Challenge: Reinforced", ["text"] = "Instant\nSecurity is heightened. Many additional forces were brought in to protect this site.\n\nIncreases Spoils by 15% when selected.\n\n[Unlock: Complete a Tier 2 Ritual Site then speak with Ranger Captain Lilatha in Silvermoon City. The tier required reduces each week. ]" }
entries[1288916] = { ["name"] = "Unlock Challenge: Magical Alarm Bells", ["text"] = "Instant\nDisruptions at the site trigger forces to be summoned to the location of the incident. The more disruptive the incident, the greater the force summoned.\n\nIncreases Spoils by 13% when selected.\n\n[Unlock: Complete a Tier 4 Ritual Site then speak with Lady Darkglen in Silvermoon City. The tier required reduces each week. ]" }
entries[1288917] = { ["name"] = "Unlock Challenge: Patrols", ["text"] = "Instant\nSecurity of the Ritual Site has been increased. Powerful members of the faction are now patrolling the site. It is best to avoid them if possible." }
entries[1288918] = { ["name"] = "Unlock Challenges: Malevolent Boons", ["text"] = "Instant\nThe enemies in the site are using dark obelisks to empower their forces. Disable these or face them with their malevolent boons.\n\nIncreases Spoils by 20% when selected.\n\n[Unlock: Complete a Tier 2 Ritual Site then speak with Lady Darkglen in Silvermoon City. The tier required reduces each week. ]" }
entries[1288920] = { ["name"] = "Unlock Challenge: Embers", ["text"] = "Instant\nThe overwhelming power of the ritual is felt throughout the site, embers of power can be found empowering nearby enemies and their leader.\n\nIncreases Spoils by 25% when selected.\n\n[Unlock: Find Embers of Power from a Tier 4 Ritual Site. The tier required reduces each week. ]" }
