entries[1289745] = { ["name"] = "Liquid Luster", ["text"] = "2 sec cast\nReagents:\nNeutralized Venom Clot , Cursebound Globe , Tranquility Bloom (8), Sanguithorn (6), Sunglass Vial (5)\nOptional Reagents:\nVendor:\nSkull of Er'inye\nZone:\nVaults of Atal'Utek\nCost:\n2500\n150\n\nUse: Drink to apply Lustrous Gleam every 6 seconds for 30 sec seconds, increasing your Versatility by 358 while this potion is active.\n\nApplications of Lustrous Gleam stack up to 5 times.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
entries[1289746] = { ["name"] = "Alluring Nostrum", ["text"] = "2 sec cast\nReagents:\nNeutralized Venom Clot , Cursebound Globe , Tranquility Bloom (8), Sanguithorn (3), Mana Lily (3), Sunglass Vial (5)\nOptional Reagents:\nVendor:\nSecond Mate Sluggs\nZone:\nThe Coiled Isle\nCost:\n150\n\nUse: Accept the Void's gifts, empowering your damaging spells and abilities a chance to deal 10724 Shadow damage to your current target and up to 4 nearby enemies for 30 sec.\n\nThe Void's boons will burden you, slowing your movement speed by 15%, stacking up to 5 times.\n81\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"" }
